void check(bool value,const char* text){if(!value)throw std::runtime_error(text);}template<class F>void fails(F f){bool stopped=false;try{f();}catch(const std::exception&){stopped=true;}check(stopped,"Required event memory error did not stop");}
struct Bytes {std::map<U,std::uint8_t> data;void add(U at,U n){for(U i=0;i<n;++i)data[at+i]=0;}U get(U at,U width){U n=0;for(U i=0;i<width;++i)n|=U(data.at(at+i))<<(i*8);return n;}void put(U at,U width,U n){for(U i=0;i<width;++i)data.at(at+i)=std::uint8_t(n>>(i*8));}};
void basic(){Bytes bytes;bytes.add(0x4f2bc8,32);for(U at:{0x1300000u,0x1301000u,0x1302000u,0x1303000u})bytes.add(at,128);bytes.add(0xffffffe8,24);for(U i=0;i<3;++i){bytes.put(0x4f2bc8+i*8,4,2);bytes.put(0x4f2bcc+i*8,4,0x1300000+i*0x1000);}unsigned reads=0,writes=0;std::vector<U> read_addresses;bool replace=false;MissionEventResourceBindings b;b.read=[&](U at,unsigned width){++reads;read_addresses.push_back(at);const U value=bytes.get(at,width);if(replace&&at==0x1300004){replace=false;bytes.put(0x4f2bcc,4,0x1303000);bytes.put(0x4f2bc8,4,1);}return value;};b.write=[&](U at,unsigned width,U value){++writes;check(width==4||value<(1u<<(width*8)),"Store was not narrowed to width");bytes.put(at,width,value);};
 EventRecordView held;{MissionEventMemory memory(b);auto view=memory.event_at(0);held=view;check(read_addresses==std::vector<U>{0x4f2bc8,0x4f2bcc}&&view.source_address()==0x1300000&&view.byte_size()==24,"Fresh lookup metadata/order");view.write(0,4,0x11223344);check(view.read(1,2)==0x2233,"WORD byte alias");view.write(1,2,0xffffaabb);check(view.read(0,4)==0x11aabb44,"WORD store byte preservation");view.write(2,1,0xffffffee);check(view.read(0,4)==0x11eebb44,"BYTE store byte preservation");check(memory.trigger_at(1).source_address()==0x1301020&&memory.action_at(1).source_address()==0x1302020,"Record strides");
  for(auto table:{EventTable::events,EventTable::triggers,EventTable::actions}){const U base=memory.table_base(table),stride=table==EventTable::events?24:32;check(memory.current_index(table,base+stride)==1&&memory.encoded_reference(table,1,1)==base+stride,"Reference codec");check(memory.current_index(table,base+stride*2,0)==2&&memory.encoded_reference(table,2,0)==base+stride*2,"Zero-length one-past reference");fails([&]{memory.current_index(table,base+stride*2);});fails([&]{memory.referenced_record(table,base+stride*2);});fails([&]{memory.current_index(table,base+1,0);});fails([&]{memory.encoded_reference(table,1,2);});fails([&]{memory.current_index(table,base-1,0);});}
  bytes.put(0x1300004,4,0x12345678);replace=true;check(view.read(4,4)==0x12345678&&memory.event_at(0).source_address()==0x1303000,"Callback current-base replacement");const unsigned before=reads;view.write(8,4,77);check(bytes.get(0x1300008,4)==77&&bytes.get(0x1303008,4)==0&&reads==before,"Captured view reselected metadata");fails([&]{memory.current_index(EventTable::events,view.source_address());});fails([&]{memory.event_at(1);});
  for(unsigned width:{0u,3u,8u}){fails([&]{view.read(0,width);});fails([&]{view.write(0,width,0);});}fails([&]{view.read(23,2);});fails([&]{view.write(24,1,0);});fails([&]{view.read(0xffffffffu,1);});fails([&]{memory.read(0xffffffffu,2);});fails([&]{memory.write(0xffffffffu,4,0);});fails([&]{memory.event_at(std::numeric_limits<std::size_t>::max());});fails([&]{memory.count_bits(static_cast<EventTable>(99));});
  bytes.put(0x4f2bc8,4,0);bytes.put(0x4f2bcc,4,0);check(memory.encoded_reference(EventTable::events,0,0)==0&&memory.current_index(EventTable::events,0,0)==0,"Empty null table reference");fails([&]{memory.event_at(0);});bytes.put(0x4f2bc8,4,1);fails([&]{memory.event_at(0);});bytes.put(0x4f2bcc,4,0xffffffe8);auto last=memory.event_at(0);last.write(20,4,0xabcdef12);check(memory.read(0xfffffffc,4)==0xabcdef12&&memory.read(0xffffffff,1)==0xab,"Top address record access");fails([&]{memory.encoded_reference(EventTable::events,1,0);});bytes.put(0x4f2bc8,4,2);fails([&]{memory.event_at(0);});bytes.put(0x4f2bc8,4,0x80000000);check(memory.count_bits(EventTable::events)==0x80000000,"Raw count bits changed");fails([&]{memory.event_at(0);});
 }const unsigned before=reads;fails([&]{held.read(0,1);});fails([&]{held.write(0,1,0);});check(reads==before,"Expired view reached memory provider");EventRecordView empty;fails([&]{empty.read(0,1);});MissionEventResourceBindings missing;MissionEventMemory invalid(missing);fails([&]{invalid.read(0,1);});fails([&]{invalid.write(0,1,0);});fails([&]{invalid.reset();});check(writes>0,"No actual writes");
}
void stock(const std::filesystem::path& folder){AssetStore assets(folder);std::ifstream file(folder/"Df.exe",std::ios::binary);AssetBytes exe((std::istreambuf_iterator<char>(file)),{});Fixed3 listener{};U yaw=0;MissionAudioFrameCells cells{0,listener,yaw};const TerrainGeometry* terrain=nullptr;MissionSoundRuntime sound(assets,exe,cells,terrain,{});const auto& raw=sound.asset_bindings();const auto source=assets.read("C05M07.BMS").bytes;const auto mission=decode_mission(source);U objects=0;for(const auto& group:mission.object_groups)objects+=U(group.size());const U event_offset=268+objects*96+17408+2048+640;check(std::uint64_t(event_offset)+12+mission.events.size()*24+(mission.triggers.size()+mission.actions.size())*32==source.size(),"Validated BMS event extent");
 const U name=raw.call(0x497f60,{32,16,0,0});check(name!=0,"Name allocation failed");const std::string filename="C05M07.BMS";for(U i=0;i<=filename.size();++i)raw.write(name+i,1,i<filename.size()?U(filename[i]):0);MissionEventMemory* current=nullptr;bool replace=false;U original_base=0,original_count=0;unsigned provider_reads=0,marker_calls=0;MissionEventResourceBindings b;b.read=[&](U at,unsigned width){++provider_reads;const U value=raw.read(at,width);if(replace&&at==original_base+4){replace=false;raw.write(0x4f2bcc,4,original_base+24);raw.write(0x4f2bc8,4,original_count-1);}return value;};b.write=raw.write;b.call=[&](U site,const std::vector<U>& args)->U{if(site==0x42eea0||site==0x42f020){check(args.empty()&&current,"Marker view fixture context");++marker_calls;auto view=site==0x42eea0?current->event_at(0):current->action_at(0);view.write(0,4,view.read(0,4)^0x1000000u);return 0;}return raw.call(site,args);};
 EventRecordView retained;{MissionEventMemory memory(b);current=&memory;const auto open=[&](){check(raw.call(0x499120,{name})!=0xffffffffu,"Actual BMS open failed");check(raw.call(0x4992d0,{event_offset,0})==event_offset,"Actual event file cursor");};open();memory.load_current_file();check(raw.call(0x4992d0,{0,1})==source.size(),"Actual BMS payload read");raw.call(0x499020,{});original_base=memory.table_base(EventTable::events);original_count=memory.count_bits(EventTable::events);check(original_count==mission.events.size()&&original_count>1,"Actual event count");auto view=memory.event_at(0);retained=view;
  for(std::size_t i=0;i<mission.events.size();++i){auto event=memory.event_at(i);check(memory.current_index(EventTable::triggers,event.read(4,4),mission.events[i].trigger_count())==mission.events[i].trigger_index(),"Actual trigger reference codec");check(memory.current_index(EventTable::actions,event.read(8,4),mission.events[i].action_count())==mission.events[i].action_index(),"Actual action reference codec");}
  const U reload=view.read(14,2),other_bytes=view.read(20,4)&0xffffff00u;view.write(12,2,0x7788);view.write(20,1,1);check(raw.read(original_base+12,2)==0x7788&&view.read(14,2)==reload&&view.read(20,4)==(other_bytes|1),"Current view mutation/width aliases");const U captured_reference=view.read(4,4);replace=true;check(view.read(4,4)==captured_reference&&memory.event_at(0).source_address()==original_base+24&&memory.count_bits(EventTable::events)==original_count-1,"Actual callback base/count replacement");view.write(20,1,0x7e);check(raw.read(original_base+20,1)==0x7e,"Captured view kept old physical record");raw.write(0x4f2bcc,4,original_base);raw.write(0x4f2bc8,4,original_count);
  const U payload_bytes=U(mission.events.size()*24),old_word=view.read(0,4);memory.reset();check(!memory.count_bits(EventTable::events)&&view.read(0,4)==old_word&&view.read(20,1)==0x7e,"Retained view after reset");fails([&]{memory.event_at(0);});view.write(20,1,0x6d);check(raw.read(original_base+20,1)==0x6d,"Retained view write");const U reused=raw.call(0x497f60,{payload_bytes,16,0,0});check(reused==original_base,"Actual source arena hole reuse");for(U i=0;i<payload_bytes;++i)raw.write(reused+i,1,0x5a);check(view.read(0,4)==0x5a5a5a5a,"Captured view did not see reused bytes");raw.call(0x4980d0,{reused});open();memory.load_current_file();raw.call(0x499020,{});check(memory.table_base(EventTable::events)==original_base&&view.read(0,4)==(mission.events[0].words[0]^0x1000000u),"Reload/current borrowed bytes");memory.reset();check(marker_calls==4,"Required marker fixture calls");}
 const unsigned before=provider_reads;fails([&]{retained.read(0,4);});check(provider_reads==before,"Expired actual adapter touched source owner");std::cout<<"Actual BMS/source arena: captured views, callback metadata replacement, reset, retained writes, same-address reuse and reload passed\n";
}
