int main(int argc,char** argv){try{basic();if(argc==2)stock(argv[1]);else check(argc==1,"Usage");std::cout<<"Event memory checks passed; marker services are explicit fixtures\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
